  void sse_encode_quarter_gst_row(
    QuarterGstRow self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.quarter, serializer);
    sse_encode_String(self.cgst, serializer);
    sse_encode_String(self.sgst, serializer);
    sse_encode_String(self.igst, serializer);
    sse_encode_String(self.inputCredit, serializer);
    sse_encode_String(self.net, serializer);
  }

  @protected
  void sse_encode_received_row(ReceivedRow self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.message, serializer);
    sse_encode_bool(self.conflict, serializer);
  }

  @protected
  void sse_encode_report_row(ReportRow self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.year, serializer);
    sse_encode_list_figure_row(self.income, serializer);
    sse_encode_list_figure_row(self.incomeTax, serializer);
    sse_encode_String(self.incomeTaxNote, serializer);
    sse_encode_tone(self.incomeTaxTone, serializer);
    sse_encode_list_quarter_gst_row(self.gst, serializer);
    sse_encode_list_client_row(self.clients, serializer);
    sse_encode_list_String(self.quarters, serializer);
    sse_encode_u_32(self.quarterToFile, serializer);
    sse_encode_list_String(self.iffMonths, serializer);
    sse_encode_u_32(self.iffMonthToFile, serializer);
  }

  @protected
  void sse_encode_sent_row(SentRow self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.snapshot, serializer);
    sse_encode_String(self.manifest, serializer);
    sse_encode_String(self.message, serializer);
  }

  @protected
  void sse_encode_sync_status_row(
    SyncStatusRow self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.summary, serializer);
    sse_encode_bool(self.changed, serializer);
    sse_encode_opt_String(self.sha256, serializer);
  }

  @protected
  void sse_encode_time_input(TimeInput self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_String(self.date, serializer);
    sse_encode_String(self.duration, serializer);
    sse_encode_String(self.note, serializer);
  }

  @protected
  void sse_encode_tone(Tone self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    sse_encode_i_32(self.index, serializer);
  }

  @protected
  void sse_encode_u_32(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint32(self);
  }

  @protected
  void sse_encode_u_8(int self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putUint8(self);
  }

  @protected
  void sse_encode_unit(void self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
  }

  @protected
  void sse_encode_usize(BigInt self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    serializer.buffer.putBigUint64(self);
  }
}

@sealed
class CompterAppImpl extends RustOpaque implements CompterApp {
  // Not to be used by end users
  CompterAppImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  CompterAppImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_CompterApp,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_CompterApp,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_CompterAppPtr,
  );

  /// Record an expense paid from the bank
  Future<ExpenseRow> addExpense({required ExpenseInput input}) => RustLib
      .instance
      .api
      .crateApiAppCompterAppAddExpense(that: this, input: input);

  Future<ProjectDetail> addMilestone({
    required String projectId,
    required MilestoneInput input,
  }) => RustLib.instance.api.crateApiAppCompterAppAddMilestone(
    that: this,
    projectId: projectId,
    input: input,
  );

  Future<ProjectDetail> createProject({required ProjectInput input}) => RustLib
      .instance
      .api
      .crateApiAppCompterAppCreateProject(that: this, input: input);

  /// Where credit note `number`'s PDF is, writing it first if it is missing
  Future<String> creditNotePdf({required String number}) => RustLib.instance.api
      .crateApiAppCompterAppCreditNotePdf(that: this, number: number);

  /// Remove an expense and its ledger posting
  Future<void> deleteExpense({required String id}) => RustLib.instance.api
      .crateApiAppCompterAppDeleteExpense(that: this, id: id);

  /// Correct an expense; its ledger posting is replaced with it
  Future<ExpenseRow> editExpense({
    required String id,
    required ExpenseInput input,
  }) => RustLib.instance.api.crateApiAppCompterAppEditExpense(
    that: this,
    id: id,
    input: input,
  );

  /// The expenses of the financial year starting in April of `year`, by date
  Future<ExpenseList> expenses({required int year}) => RustLib.instance.api
      .crateApiAppCompterAppExpenses(that: this, year: year);

  /// Write quarter `quarter` (1 to 4) of `year`'s GSTR-1 for the GST portal. The B2B part of
  /// a month whose IFF was filed is left out.
  Future<ExportRow> exportGstr1({
    required int year,
    required int quarter,
    required bool firstMonthFiled,
    required bool secondMonthFiled,
  }) => RustLib.instance.api.crateApiAppCompterAppExportGstr1(
    that: this,
    year: year,
    quarter: quarter,
    firstMonthFiled: firstMonthFiled,
    secondMonthFiled: secondMonthFiled,
  );

  /// Write the IFF for `month`, a position in `ReportRow::iff_months` of `year`
  Future<ExportRow> exportIff({required int year, required int month}) =>
      RustLib.instance.api.crateApiAppCompterAppExportIff(
        that: this,
        year: year,
        month: month,
      );

  Future<InvoiceDetail> invoice({required String number}) => RustLib
      .instance
      .api
      .crateApiAppCompterAppInvoice(that: this, number: number);

  /// Where invoice `number`'s PDF is, writing it first if it is missing
  Future<String> invoicePdf({required String number}) => RustLib.instance.api
      .crateApiAppCompterAppInvoicePdf(that: this, number: number);

  /// Every issued invoice, newest first
  Future<InvoiceList> invoices() =>
      RustLib.instance.api.crateApiAppCompterAppInvoices(that: this);

  /// Issue a credit note against invoice `number` and write its PDF
  Future<CreditedRow> issueCredit({
    required String number,
    required CreditInput input,
  }) => RustLib.instance.api.crateApiAppCompterAppIssueCredit(
    that: this,
    number: number,
    input: input,
  );

  /// Issue today's invoice for a pending milestone and write its PDF
  Future<IssuedRow> issueInvoice({
    required String projectId,
    required String milestoneId,
    String? rate,
  }) => RustLib.instance.api.crateApiAppCompterAppIssueInvoice(
    that: this,
    projectId: projectId,
    milestoneId: milestoneId,
    rate: rate,
  );

  /// Who has compter open, from the `lease.json` found in the sync folder: `compter is open
  /// on laptop (last seen 14:05)`, or `None` when it is this phone's lease or a stale one
  Future<String?> leaseHolder({required String leaseJson}) => RustLib
      .instance
      .api
      .crateApiAppCompterAppLeaseHolder(that: this, leaseJson: leaseJson);

  /// This phone's lease, as the JSON compter on the computer reads from `lease.json`: write
  /// it to the sync folder while the app is in use, and refresh it every minute
  Future<String> leaseJson({required String deviceName}) => RustLib.instance.api
      .crateApiAppCompterAppLeaseJson(that: this, deviceName: deviceName);

  /// Log time worked on a pending milestone of an hourly project
  Future<ProjectDetail> logTime({
    required String projectId,
    required String milestoneId,
    required TimeInput input,
  }) => RustLib.instance.api.crateApiAppCompterAppLogTime(
    that: this,
    projectId: projectId,
    milestoneId: milestoneId,
    input: input,
  );

  /// The credit note `input` would make against invoice `number`, without saving
  Future<CreditPreviewRow> previewCredit({
    required String number,
    required CreditInput input,
  }) => RustLib.instance.api.crateApiAppCompterAppPreviewCredit(
    that: this,
    number: number,
    input: input,
  );

  /// The invoice a pending milestone would get today, without saving anything. `rate` (rupees
  /// per unit) is needed when the project is billed in a foreign currency.
  Future<InvoicePreviewRow> previewInvoice({
    required String projectId,
    required String milestoneId,
    String? rate,
  }) => RustLib.instance.api.crateApiAppCompterAppPreviewInvoice(
    that: this,
    projectId: projectId,
    milestoneId: milestoneId,
    rate: rate,
  );

  /// The business profile, or `None` before it is set up (invoicing needs it)
  Future<ProfileRow?> profile() =>
      RustLib.instance.api.crateApiAppCompterAppProfile(that: this);

  /// The profile form, prefilled with what is saved or the usual first values
  Future<ProfileInput> profileInput() =>
      RustLib.instance.api.crateApiAppCompterAppProfileInput(that: this);

  Future<ProjectDetail> project({required String id}) =>
      RustLib.instance.api.crateApiAppCompterAppProject(that: this, id: id);

  /// The project list, from summaries; archived projects only when asked for
  Future<List<ProjectRow>> projects({required bool includeArchived}) =>
      RustLib.instance.api.crateApiAppCompterAppProjects(
        that: this,
        includeArchived: includeArchived,
      );

  /// Take the snapshot in `folder`, where Dart copied `compter.redb` and `manifest.json` from
  /// the computer's sync folder. A new install's empty database is simply replaced.
  Future<ReceivedRow> receiveSnapshot({required String folder}) => RustLib
      .instance
      .api
      .crateApiAppCompterAppReceiveSnapshot(that: this, folder: folder);

  /// Record all or part of a payment. On a rupee invoice `tds_or_banked` is the TDS withheld;
  /// on a foreign one it is the rupees that reached the bank.
  Future<InvoiceDetail> recordPayment({
    required String number,
    required PaymentInput input,
  }) => RustLib.instance.api.crateApiAppCompterAppRecordPayment(
    that: this,
    number: number,
    input: input,
  );

  /// The financial year starting in April of `year`, in numbers
  Future<ReportRow> report({required int year}) =>
      RustLib.instance.api.crateApiAppCompterAppReport(that: this, year: year);

  /// Save the business profile; the logo, set elsewhere, is kept
  Future<ProfileRow> saveProfile({required ProfileInput input}) => RustLib
      .instance
      .api
      .crateApiAppCompterAppSaveProfile(that: this, input: input);

  /// Write this phone's database to `folder` as `compter.redb` and `manifest.json`, for the
  /// user to save into the computer's sync folder
  Future<SentRow> sendSnapshot({
    required String folder,
    required String deviceName,
  }) => RustLib.instance.api.crateApiAppCompterAppSendSnapshot(
    that: this,
    folder: folder,
    deviceName: deviceName,
  );

  /// Settle what `receive_snapshot` couldn't: keep this phone's data (send it next), or take
  /// the snapshot in `folder`, keeping this phone's database beside it as a backup
  Future<String> settleSnapshot({
    required String folder,
    required bool keepThisPhone,
    required String deviceName,
  }) => RustLib.instance.api.crateApiAppCompterAppSettleSnapshot(
    that: this,
    folder: folder,
    keepThisPhone: keepThisPhone,
    deviceName: deviceName,
  );

  /// Where this phone's data stands against the computer's sync folder
  Future<SyncStatusRow> syncStatus() =>
      RustLib.instance.api.crateApiAppCompterAppSyncStatus(that: this);
}
